{
    struct isea_pt  v;
    double          hexwidth;
    double          sidelength; /* in hexes */
    int             d, i;
    int             maxcoord;
    struct hex      h;

    /* This is the number of hexes from apex to base of a triangle */
    sidelength = (pow(2.0, g->resolution) + 1.0) / 2.0;

    /* apex to base is cos(30deg) */
    hexwidth = cos(M_PI / 6.0) / sidelength;

